// Game home, level selection and locally saved points per student.
let gameScores={};try{gameScores=JSON.parse(localStorage.getItem('wordlab-game-scores-v1')||'{}')}catch{}
const topics=['School days','Family & home','Play & music','Jobs & helpers','Wonder 1','Food time','Animal world','Places to explore','Future & technology','Wonder 2','The Cuckoo','Dancing Tortoise'];
const covers=[9,8,2,4,3,20,28,6,1,6,0,2];
const gameNav=button('🎮 Ойын картасы',()=>{mode='adventure';session=null;render()},'control');activityBar.prepend(gameNav);
function playerKey(){return (student||'Қонақ').trim().toLocaleLowerCase()}
function playerScores(){return gameScores[playerKey()]||{xp:0,stages:{}}}
function storeGame(){try{localStorage.setItem('wordlab-game-scores-v1',JSON.stringify(gameScores))}catch{$('notice').textContent='Ойын ұпайлары бұл браузерде сақталмады.'}}
function launchGame(i,m){unit=i;mode=m;session=null;render();panel.scrollIntoView({behavior:'smooth',block:'start'})}
function adventure(){panel.classList.add('game-home');const stats=playerScores();panel.append(el('p','PLAY · LEARN · DISCOVER','eyebrow dark'),el('h2','Сөздер әлеміне саяхат!'),el('p','Деңгейді таңда. Суреттермен ойна. Ұпай жина.','activity-desc'));const status=el('div',undefined,'game-stats');status.append(el('span','👤 '+(student||'Қонақ')),el('span','⭐ '+stats.xp+' XP'),el('span','🏅 '+Object.keys(stats.stages).length+' раунд аяқталды'));panel.append(status);const map=el('div',undefined,'level-map');DATA.forEach((u,i)=>{let c=el('article',undefined,'level-card');c.append(photoForWord(u.words[covers[i]]),el('small',u.name.replace('Module','LEVEL').toUpperCase()),el('h3',topics[i]),el('p',u.words.length+' сөз · '+(stats.stages[i+':match']||stats.stages[i+':listen']?'⭐ Ойналды':'Жаңа тапсырмалар'),'muted'));const btns=el('div',undefined,'level-buttons');btns.append(button('🎧 Тыңда',()=>launchGame(i,'listen'),'primary'),button('🧩 Жұпта',()=>launchGame(i,'match'),'control'),button('📚 Үйрен',()=>launchGame(i,'learn'),'control'));c.append(btns);map.append(c)});panel.append(map,el('p','Дұрыс жауап = 10 XP. Қате болса, қайталап үйрен. Жылдамдыққа шектеу жоқ. Ұпайлар осы браузерде, енгізілген аты-жөнің бойынша сақталады.','muted'))}
const oldUpdate=updateActivity;updateActivity=function(){panel.classList.remove('game-home');if(mode==='adventure'){panel.hidden=false;$('grid').hidden=true;document.querySelector('.tools').hidden=true;panel.replaceChildren();activityBar.querySelectorAll('[data-mode]').forEach(b=>{b.classList.remove('on');b.setAttribute('aria-pressed','false')});gameNav.classList.add('on');adventure();return}gameNav.classList.remove('on');oldUpdate();if(session&&session.index<session.items.length){let hud=el('div',undefined,'round-hud');hud.id='round-hud';panel.prepend(hud);paintGameHUD()}};
function paintGameHUD(){const hud=document.getElementById('round-hud');if(!hud||!session)return;let streak=0;for(let i=session.answers.length-1;i>=0&&session.answers[i].correct;i--)streak++;hud.textContent='⭐ '+session.answers.filter(a=>a.correct).length*10+' XP  ·  🔥 '+streak+' қатарынан  ·  '+session.answers.length+'/'+session.items.length}
const gameFinish=finish;finish=function(){gameFinish();if(!session.gameAwarded){const points=session.answers.filter(a=>a.correct).length*10;let s=playerScores();s.xp+=points;s.stages[unit+':'+mode]=Math.max(s.stages[unit+':'+mode]||0,Math.round(points/(session.items.length*10)*100));gameScores[playerKey()]=s;storeGame();session.gameAwarded=true;session.earnedXP=points}const ratio=session.answers.filter(a=>a.correct).length/session.items.length;const reward=el('div',undefined,'game-reward');reward.append(el('div',ratio>=.9?'⭐⭐⭐':ratio>=.6?'⭐⭐':'⭐','reward-stars'),el('h3','+'+session.earnedXP+' XP · Жарайсың!'),button('🎮 Ойын картасына оралу',()=>{mode='adventure';session=null;render()},'primary'));panel.prepend(reward)};
// Refresh points after a response without rebuilding the active matching board.
panel.addEventListener('click',()=>paintGameHUD());
const heroStart=button('ОЙНАУДЫ БАСТАУ →',()=>{mode='adventure';session=null;render();panel.scrollIntoView({behavior:'smooth',block:'start'})},'primary hero-start');document.querySelector('.hero-copy').append(heroStart);
document.querySelector('.hero h1').innerHTML='Play with words.<br><em>Learn for life.</em>';
const footer=document.querySelector('footer');footer.append(el('p','Сөз карточкаларындағы фотореалистік бейнелер AI көмегімен жасалған.'));
mode='adventure';updateActivity();
